	private class ProjectDataTableDragProvider : GTableDragProvider<DomainFileInfo> {

		private static readonly DataFlavor DOMAIN_FILE_LIST_FLAVOR =
			DataTreeDragNDropHandler.localDomainFileFlavor;
		private static readonly DataFlavor[] ROW_DATA_FLAVORS = { DOMAIN_FILE_LIST_FLAVOR };

		ProjectDataTableDragProvider() : base(gTable, model)
    {
		}

		/* @Override */
		protected Transferable createDragTransferable(List<DomainFileInfo> items) {
			return new DomainFileTransferable(items);
		}

		private class DomainFileTransferable : Transferable {
			private List<DomainFileInfo> list;

			DomainFileTransferable(List<DomainFileInfo> list) {
				this.list = list;
			}

			/* @Override */
			public object getTransferData(DataFlavor flavor)
    {
				if (DOMAIN_FILE_LIST_FLAVOR.equals(flavor)) {
					return getDomainFileList();
				}
				throw new UnsupportedFlavorException(flavor);
			}

			private object getDomainFileList() {
				List<DomainFile> domainFileList = new();
				foreach (DomainFileInfo domainFileInfo in list) {
					domainFileList.add(domainFileInfo.getDomainFile());
				}
				return domainFileList;
			}

			/* @Override */
			public DataFlavor[] getTransferDataFlavors() {
				return ROW_DATA_FLAVORS;
			}

			/* @Override */
			public bool isDataFlavorSupported(DataFlavor flavor) {
				return DOMAIN_FILE_LIST_FLAVOR.equals(flavor);
			}
		}

	}

	private class ProjectDataTableDomainFolderChangeListener : DomainFolderChangeListener {

		// TODO: file and subfolder events are only triggered if the parent folder has been
		// "visited" which means a folder added event will NOT be followed by any child
		// folder/file added events.  This is different from the old full-refresh mechanism
		// which sent added events for everything contained within a new sub-tree.

		private bool ignoreChanges() {
			return model.loadWasCancelled() || capacityExceeded;
		}

		/* @Override */
		public void domainFolderAdded(DomainFolder folder) {
			if (ignoreChanges()) {
				return;
			}
			reload();
		}

		/* @Override */
		public void domainFileAdded(DomainFile file) {
			if (ignoreChanges()) {
				return;
			}
			checkCapacity();
			if (!capacityExceeded) {
				model.addObject(new DomainFileInfo(file, model));
				model.refresh();
			}
		}

		/* @Override */
		public void domainFolderRemoved(DomainFolder parent, string name) {
			if (ignoreChanges()) {
				return;
			}
			reload();
		}

		/* @Override */
		public void domainFileRemoved(DomainFolder parent, string name, string fileID) {
			if (ignoreChanges()) {
				return;
			}
			string path = parent.getPathname();
			List<DomainFileInfo> modelData = model.getModelData();
			foreach (DomainFileInfo domainFileInfo in modelData) {
				if (name.equals(domainFileInfo.getName()) &&
					path.equals(domainFileInfo.getPath())) {
					model.removeObject(domainFileInfo);
					break;
				}
			}
			model.refresh();
		}

		/* @Override */
		public void domainFolderRenamed(DomainFolder folder, string oldName) {
			if (ignoreChanges()) {
				return;
			}
			reload();
		}

		/* @Override */
		public void domainFileRenamed(DomainFile file, string oldName) {
			if (ignoreChanges()) {
				return;
			}
			reload();
		}

		/* @Override */
		public void domainFolderMoved(DomainFolder folder, DomainFolder oldParent) {
			if (ignoreChanges()) {
				return;
			}
			reload();
		}

		/* @Override */
		public void domainFileMoved(DomainFile file, DomainFolder oldParent, string oldName) {
			if (ignoreChanges()) {
				return;
			}
			reload();
		}

		/* @Override */
		public void domainFileStatusChanged(DomainFile file, bool fileIDset) {
			if (ignoreChanges()) {
				return;
			}
			clearInfo(file);
			table.repaint();
			plugin.getTool().contextChanged(null);
		}

	}

	/**
	 * A listener that checks for files that need to be selected after each model change.  This is
	 * required due to the asynchronous nature of the table loading and clients that wish to make
	 * selections, potentially before the table has loaded the items whose selection is desired.s
	 */
	private class SelectPendingFilesListener : ThreadedTableModelListener {

		/* @Override */
		public void loadingFinished(bool wasCancelled) {
			if (filesPendingSelection != null) {
				// we have files that are the object of selection desire
				doSetSelectedDomainFiles(filesPendingSelection);
				filesPendingSelection = null;
			}
		}

		/* @Override */
		public void loadPending() {
			// don't care
		}

		/* @Override */
		public void loadingStarted() {
			// don't care
		}
	}

